def calculate_T2(N):
    total_sum = 0
    divisor = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # {x} = x - floor(x)
            frac_part = (a * b) / divisor - (a * b) // divisor
            total_sum += frac_part
    return total_sum

def calculate_target(N):
    return (N**2 - 1) / 2

N_values = [6, 7, 8]
results = {}

for N in N_values:
    T2_N = calculate_T2(N)
    Target_N = calculate_target(N)
    results[N] = {
        "T2(N)": T2_N,
        "Target": Target_N,
        "Match": abs(T2_N - Target_N) < 1e-9
    }

print("--- Results ---")
for N, res in results.items():
