def S_mod(M):
    """Calculates S_mod(M) = sum_{a=1}^{M-1} sum_{b=1}^{M-1} (ab mod M)"""
    M_minus_1 = M - 1
    total_sum = 0
    for a in range(1, M):
        for b in range(1, M):
            total_sum += (a * b) % M
    return total_sum

def target_S_mod(M):
    """Calculates the target value S_mod(M) = M(M-1)^2 / 2 - 1"""
    # Target S_mod(M) = (M(M-1)^2 - 2) / 2
    return (M * (M - 1)**2 - 2) // 2

